#pragma warning disable CA1725
using ClosedXML.Excel;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Purchases;
namespace WhatsBiz.Infrastructure.Purchases;
public sealed class PurchaseSpreadsheetService:IPurchaseSpreadsheetService{public byte[] Export(IReadOnlyCollection<PurchaseInvoice> rows){using var w=new XLWorkbook();var s=w.Worksheets.Add("Purchases");var h=new[]{"Purchase No","Supplier Invoice","Date","Supplier","Warehouse","Grand Total","Paid","Outstanding","Status"};for(var i=0;i<h.Length;i++)s.Cell(1,i+1).Value=h[i];var r=2;foreach(var x in rows){s.Cell(r,1).Value=x.InvoiceNumber;s.Cell(r,2).Value=x.SupplierInvoiceNo;s.Cell(r,3).Value=x.InvoiceDate.DateTime;s.Cell(r,4).Value=x.Supplier.SupplierName;s.Cell(r,5).Value=x.Warehouse.WarehouseName;s.Cell(r,6).Value=x.GrandTotal;s.Cell(r,7).Value=x.PaidAmount;s.Cell(r,8).Value=x.BalanceAmount;s.Cell(r++,9).Value=x.Status;}s.Columns().AdjustToContents();return Bytes(w);}public byte[] Template(){using var w=new XLWorkbook();var s=w.Worksheets.Add("Purchase Import");var h=new[]{"SupplierCode","SupplierInvoiceNo","InvoiceDate","WarehouseCode","ProductCode","Barcode","BatchNo","ExpiryDate","Quantity","FreeQuantity","PurchasePrice","MRP","SellingPrice","DiscountPercentage","GSTPercentage"};for(var i=0;i<h.Length;i++)s.Cell(1,i+1).Value=h[i];s.Cell(2,9).Value=1;s.Cell(2,10).Value=0;s.Columns().AdjustToContents();return Bytes(w);}private static byte[] Bytes(XLWorkbook w){using var m=new MemoryStream();w.SaveAs(m);return m.ToArray();}}
